import { selectors, contactContract } from '../../../support/m01';

function home() {
  cy.location('pathname').should('eq', '/');
  cy.get('main h1').should('be.visible').and('contain.text', 'بسته‌های بارکد،');
  cy.get('main h1 em').should('have.text', 'با امضای برند شما.');
  cy.get('#products h2').should('contain.text', 'بستهٔ مناسب شما کدام است؟');
}

describe('M01 first smoke — real guest desktop', () => {
  it('N01-TC01 — subset: direct public home entry renders its distinct identity', () => {
    cy.visit('/');
    home();
    cy.get('nav[aria-label="ناوبری اصلی"]').should('be.visible');
    cy.screenshot('N01-TC01-home');
  });
  it('N01-TC02 — subset: home reload retains route and distinct home content', () => {
    cy.visit('/');
    home();
    cy.reload();
    home();
    cy.screenshot('N01-TC02-reloaded');
  });
  it('N05-TC01 — subset: visible telephone and browser destination agree without dialing', () => {
    cy.visit('/');
    home();
    contactContract();
    cy.get(selectors.phone).should('have.attr', 'href', 'tel:+982192127');
  });
  it('N05-TC02 — subset: visible email and browser recipient agree without sending', () => {
    cy.visit('/');
    home();
    cy.get(selectors.email).should('be.visible').and('have.attr', 'href', 'mailto:ezpost@tapin.ir');
    cy.get(selectors.email).find('strong').should('have.text', 'ezpost@tapin.ir');
  });
});
